import sys
import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0

    n = int(input[index])
    m = int(input[index + 1])
    s = int(input[index + 2])
    index += 3

    graph = {i: {} for i in range(1, n + 1)}

    for _ in range(m):
        u = int(input[index])
        v = int(input[index + 1])
        w = int(input[index + 2])
        index += 3
        graph[u][v] = w
        graph[v][u] = w

    original_distances = dijkstra(graph, s)

    max_unhappy_friends = 0

    for city_to_destroy in range(1, n + 1):
        if city_to_destroy == s:
            continue

        modified_graph = {i: graph[i].copy() for i in graph}
        del modified_graph[city_to_destroy]

        for node in modified_graph:
            if city_to_destroy in modified_graph[node]:
                del modified_graph[node][city_to_destroy]

        new_distances = dijkstra(modified_graph, s)
        unhappy_friends = sum(1 for city in range(1, n + 1) if city != s and city != city_to_destroy and new_distances.get(city, float('inf')) > original_distances[city])
        max_unhappy_friends = max(max_unhappy_friends, unhappy_friends)

    print(max_unhappy_friends)

if __name__ == "__main__":
    main()
